function UIBambooMainDialog:PlayTimeline()
    if self._isPlayTimeLine then
        return
    end

    self._isPlayTimeLine = true
    ---@type ChapterUtils
    local ChapterUtils = import('Game.Chapter.ChapterUtils')
    ChapterUtils.TestBambooChapter(function(loader, go)
        SceneManagement:GetInstance():SetActive(Constants.IdSceneSetting34, false)
        Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, true)

        self._plotGo = go
        self._plotLoader = loader
        self.controller.gameObject.transform.localPosition = Vector3(9999, 9999, 9999)
        URPCameraController:SetMainCameraActive(false)
        self.firstAnimStart = true
    end, function()
        Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, false)
        SceneManagement:GetInstance():SetActive(Constants.IdSceneSetting34, true)
        self.controller.gameObject.transform.localPosition = Vector3(0, 0, 0)
        KTool.SafeDelete(self._plotGo)
        if self._plotLoader then
            self._plotLoader:Release(true)
        end
        URPCameraController:SetMainCameraActive(true)
        self._isPlayTimeLine = false
    end)
end

function UIBambooMainDialog:OnFocus(focus)
    if focus then
        GameUtils.RefreshTopGoods(Constants.UITypeIds.UIBambooMainDialog)
        local cam = GameObject.Find("BambooCamera")
        if cam then
            local urpBase = cam:GetComponent(typeof(URPBaseCamera))
            urpBase:CopyCamera() 
        end

        if focus and self._isPlayTimeLine then
            URPCameraController:SetMainCameraActive(false)
        end
    end
end

--展示乱七八糟的动画
function UIBambooMainDialog:ShowAnimator()
    local mapId = checkNumber(BambooUtils.GetCurMapId())
    --如果有正在挑战的
    if mapId > 0 then

    else
        mapId = BambooQuestComponent:GetFinishMapId()
        --如果有刚通关
        if mapId > 0 then
            local vo = BambooUtils.GetBambooActivityCopyVo(mapId)
            if vo then
                GameUtils.Toast(localize("已完成章节")..vo.name)
            end
            local go = self.PointGroup.transform:Find("Item_"..mapId)
            if go then
                local scr = CfUtils.GetLuaScr(go, UIBambooMainMapPointNode)
                if scr then
                    scr:RefreshIsSelect(false)
                    scr:PlayAni("Unlock-Complete")
                    cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.417))
                end
            end
            local t = BambooQuestComponent:GetNewUnlockMapId()
            if t and table.count(t) > 0 then
                for k, v in pairs(t) do
                    go = self.PointGroup.transform:Find("Item_"..v)
                    if go then
                        local scr = CfUtils.GetLuaScr(go, UIBambooMainMapPointNode)
                        if scr then
                            scr:PlayAni("Lock-Unlock")
                            cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.5))
                            scr:RefreshIsSelect(true)
                        end
                    end
                end
            end
        end
    end
end

function UIBambooMainDialog:Awake()
    GameUtils.RefreshTopGoods(Constants.UITypeIds.UIBambooMainDialog)
    CfUtils.SetActive(self.BtnCardDraw,false)
end

function UIBambooMainDialog:FillSelf()
    SetButtonAction(self.BtnReward, Bind(self, self.OnBtnRewards))
    SetButtonAction(self.BtnChallenge, Bind(self, self.OnBtnChallenge))
    SetButtonAction(self.BtnReview, Bind(self, self.OnBtnReview))
    SetButtonAction(self.BtnShop, Bind(self, self.OnBtnShop))
    SetButtonAction(self.BtnCardDraw, Bind(self, self.OnBtnDrawCards))
    SetButtonAction(self.BtnExplain, Bind(self, self.OnBtnExplain))
    SetButtonAction(self.Root.transform:Find("Contianer/SafeAreaGroup/TitleGroup/LayoutTitle"), Bind(self, self.PlayTimeline))

    CfUtils.FillText(self.TxtNumber, BambooUtils.GetCurIntegral(self._activityUuid))
    CfUtils.FillImage(self.ImgIcon, GoodsConfMgr:GetInstance():GetPhotoPathById(Constants.Currency.BambooIntegralCurrency))

    --self:FillOpenDayLock()
    self:FillMapPoints()
    self:FillTime()

    local pos = self:GetBtnRewardPos()
    if pos then
        self.BtnReward.localPosition = Vector3(pos.x, pos.y, 0)
    end

    local redGo = GameUtils.GetRedPointGo(self.BtnReward)
    if redGo then
        local isHaveReard = BambooUtils.IsHaveCanDrawReward(self._activityId)
        CfUtils.SetActive(redGo, isHaveReard)
    end
end

function UIBambooMainDialog:FillTime()
    local data = BambooQuestComponent:GetBambooActivityDojo(self._activityUuid)
    local curTime = os.time()
    local startTime = curTime + data.startTime
    local closeTime = curTime + data.closeTime
    --CfUtils.FillText(self.Text2, os.date("%Y.%m.%d", startTime).." 5:00:00 ~ "..os.date("%Y.%m.%d", closeTime).." 4:59:59")
    ---@type ActivityUtils
    local ActivityUtils         = import("Game.Activity.ActivityUtils")
    CfUtils.FillText(self.Text2, ActivityUtils.ConventActivityDurationTime(startTime, closeTime))
end

--解锁天数显示
function UIBambooMainDialog:FillOpenDayLock()
    local openDay = BambooUtils.GetActivityOpenDay(self._activityUuid)
    if openDay < 0 then
        printError("结束倒计时错误")
        return 
    end

    --写死的俩个
    for i = 1, 2 do
        KTool.SetActive(self["LockMask"..i], not (openDay >= i))
        if openDay < i then
            CfUtils.FillText(self["LockText"..i], localize("_num_天后开放", {_num_ = i}))
        end
    end
end

--绘制副本
function UIBambooMainDialog:FillMapPoints()
    if not self._allMapPoint then
        return
    end

    for i = 1, #self._allMapPoint do
        local id = self._allMapPoint[i]
        local go = self["Item_"..id]
        if go then
            local pos = self:GetChapterPos(id)
            if pos then
                go.transform.localPosition = Vector3(pos.x, pos.y, 0)
            end

            local scr = CfUtils.GetLuaScr(go, UIBambooMainMapPointNode)
            if scr then
                local vo = BambooUtils.GetBambooActivityCopyVo(id)
                scr:Refresh(vo, self._activityUuid, function()
                    if BambooUtils.IsAcrivityEnd(self._activityUuid) then
                        GameUtils.Toast(localize("活动已关闭"))
                        return
                    end

                    local curId = checkNumber(BambooUtils.GetCurMapId())
                    if curId > 0 then
                        if checkNumber(id) ~= checkNumber(curId) then
                            GameUtils.Toast(localize("当前已有挑战关卡"))
                            return
                        end
                    end

                    local isUnlock, str = BambooUtils.IsUnlockMap(id, self._activityUuid)
                    if not isUnlock then
                        GameUtils.Toast(str)
                        return
                    end
                    BambooQuestComponent:ActivityQuestEnterChapterReq(self._activityUuid, id, function()
                        CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.UIBambooCheckpointDialog, parameters = {activityUuid = self._activityUuid, mapId = id}}, {
                            {id = Constants.UITypeIds.UIBambooMainDialog},
                        })
                    end)
                end)
                
                local mapId = checkNumber(BambooUtils.GetCurMapId())
                scr:RefreshIsSelect(checkNumber(id) == checkNumber(mapId))

                local isUnlock, str = BambooUtils.IsUnlockMap(id, self._activityUuid)
                local isPass = BambooUtils.IsPassMap(vo.id)

                if isUnlock then
                    if isPass then 
                        scr:PlayAni("Complete")
                    else
                        scr:PlayAni("Unlock")
                    end
                else
                    scr:PlayAni("Lock")
                end
            end
        end
    end
end

function UIBambooMainDialog:GetChapterPos(id)
    if isNull(self._goPar) then
        self._goPar = GameObject.Find("3DPosition")
    end
    if isNull(self._goPar) then
        return nil
    end
    if isNull(self._cam) then
        self._cam = GameObject.Find("BambooCamera")
        self._cam = self._cam.gameObject:GetComponent(typeof(Camera))
    end

    local go = self._goPar.transform:Find("Item_"..id)
    if isNull(go) then
        return nil
    end

    local pos = CfUtils.WorldPosition2UIPosition(go.position, self.PointGroup, self._cam)
    return pos
end

function UIBambooMainDialog:GetBtnRewardPos()
    if isNull(self._goPar) then
        self._goPar = GameObject.Find("3DPosition")
    end
    if isNull(self._goPar) then
        return nil
    end
    if isNull(self._cam) then
        self._cam = GameObject.Find("BambooCamera")
        self._cam = self._cam.gameObject:GetComponent(typeof(Camera))
    end
    
    local go = self._goPar.transform:Find("Item_btnreward")
    if isNull(go) then
        return nil
    end
    local pos = CfUtils.WorldPosition2UIPosition(go.position, self.Root.transform:Find("Contianer"), self._cam)
    return pos
end

