function UIBambooMainDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()

        KCookie.Set("LastChallengeQuestId", 0)
        local argument = self.controller.Argument.parameters
        if not argument then
            return
        end
        Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, false)
        self._activityUuid = checkNumber(argument.activityUuid)  
        if self._activityUuid == 0 then
            return
        end
        
        self._activityId = BambooUtils.GetActivityId(self._activityUuid)    --活动id
        if self._activityId == 0 then
            return
        end

        self._isEntryQuest = checkBool(BambooQuestComponent:GetIsEntryQuest())
        --战斗退出来 的
        --if self._isEntryQuest then
        --    self._isEntryUIBambooCheckpointDialog = true
        --else
            self._allMapPoint = BambooUtils.GetBamBooAllMapCopy(self._activityId)
    
            local isTrue = false
            GameUtils.ShowBlackOverlay(nil, function()
                while not isTrue do
                    coroutine.yield(Yielders.EndOfFrame)
                end
            end)
            sceneManagement:AppendScene(Constants.IdSceneSetting34, true)
            while not sceneManagement:GetAppendingScene(Constants.IdSceneSetting34) do
                coroutine.yield(Yielders.EndOfFrame)
            end
        --end

        --local go = GameObject.Find("BambooWorldCanvas")
        --self.PointGroup = go.transform:Find("BambooMain3DPoint/Root/Contianer/MapGroup/PointGroup")

        local isFirst = CfUtils.GetLocalData("UIBambooMainDialogFirst")
        if checkNumber(isFirst) == 0 then
            CfUtils.WriteLocalData("UIBambooMainDialogFirst", 1)
            self:PlayTimeline()
            while self.firstAnimStart == false do
                CoYield()
                printInfo("UIBambooMainDialogFirst:等待动画播放")
            end
        end
        
        isTrue = true
    end))
    return coWait
end

