function UIBambooMainDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local ActivityUtils = import("Game.Activity.ActivityUtils")
        ActivityUtils.UpdateActivityMainRedPointState(self._activityUuid, BambooUtils.IsHaveCanDrawReward(self._activityUuid) and 0 or 1)
        --if not self._isEntryQuest then
            sceneManagement:UnloadAppendedSceneById(Constants.IdSceneSetting34)
        --end
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

